import MovieElement from "./MovieElement";

export default function MovieList({ movies, isLoading, error, setWatched }) {
  return (
    <ul className="list list-movies">
      {movies?.map((movie) => (
        <MovieElement movie={movie} setWatched={setWatched} />
      ))}
    </ul>
  );
}
